// MODE override: 'check' (no writes) | 'test' (1 translation) | 'all'. Set back to 'check' after the run.
const MODE = 'all';
const cfg = $('Config').first().json;
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 300)); }
function h(s) { let x = 5381; for (let i = 0; i < s.length; i++) { x = ((x * 33) ^ s.charCodeAt(i)) >>> 0; } return x; }
const items = []; const skip = []; let total = 0;
for (const k of b.keys) {
  const spec = cfg.K[String(k.key_id)]; if (!spec) { continue; }
  const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation); }
  const en = m.en || '';
  if (k.is_archived || k.is_plural) { skip.push([k.key_id, 'archived/plural']); continue; }
  if (h(en) !== spec.h) { skip.push([k.key_id, 'EN changed']); continue; }
  const tr = [];
  for (const iso of cfg.langs) {
    total++;
    if (String(m[iso] || '').trim()) { skip.push([k.key_id, iso, 'already filled']); continue; }
    const t = spec.c ? en : spec.t[iso];
    if (typeof t !== 'string') { skip.push([k.key_id, iso, 'no text']); continue; }
    tr.push({ language_iso: iso, translation: t, is_unverified: true });
  }
  if (tr.length) { items.push({ key_id: k.key_id, translations: tr }); }
}
const found = b.keys.filter(function (k) { return cfg.K[String(k.key_id)]; }).length;
let sel = items;
if (MODE === 'test') { sel = items.filter(function (x) { return String(x.key_id) === '958669858'; }).slice(0, 1); if (sel.length) { sel = [{ key_id: sel[0].key_id, translations: sel[0].translations.filter(function (t) { return t.language_iso === 'de'; }) }]; } }
const reqs = [];
for (let i = 0; i < sel.length; i += 4) { const part = sel.slice(i, i + 4); reqs.push({ body: JSON.stringify({ keys: part }), n: part.reduce(function (a, x) { return a + x.translations.length; }, 0) }); }
const n = sel.reduce(function (a, x) { return a + x.translations.length; }, 0);
return [{ json: { mode: MODE, keys_expected: Object.keys(cfg.K).length, keys_found: found, slots: total, to_write: n, skipped: skip.length, skip_sample: skip.slice(0, 25), requests: reqs } }];

// Nothing is written in MODE 'check'.
const d = $input.first().json;
if (d.mode !== 'test' && d.mode !== 'all') { return []; }
return d.requests.map(function (r) { return { json: r }; });

const cfg = $('Config').first().json;
const mode = $('Build writes').first().json.mode;
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { return [{ json: { error: 'read-back failed', body: JSON.stringify(b).slice(0, 300) } }]; }
let match = 0, empty = 0; const diff = [];
for (const k of b.keys) {
  const spec = cfg.K[String(k.key_id)]; if (!spec) { continue; }
  const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = t.translation; }
  for (const iso of cfg.langs) { const want = spec.c ? m.en : spec.t[iso]; const v = m[iso]; if (v === want) { match++; } else if (!String(v || '').trim()) { empty++; } else { diff.push([k.key_id, iso, String(v).slice(0, 120)]); } }
}
const res = $('WRITE translations').all().map(function (x) { return { status: x.json.statusCode, written: ((x.json.body || {}).keys || []).length, errors: (x.json.body || {}).errors || null }; });
return [{ json: { mode: mode, write_results: res, readback: { match: match, still_empty: empty, different: diff.length, diff_sample: diff.slice(0, 15) } } }];
